        return ("evad" in r) or (r == "evader")
    def is_pu(r):
        r = (r or "").replace("-", "_")
        return ("purs" in r) or (r == "pursuer")

    pursuer = True
    if is_pu(self_role) and not is_ev(self_role):
        pursuer = True
    elif is_pu(opp_role) and not is_ev(opp_role):
